-- ----------------------------------------------------------------------------
-- Table: "public"."alumni_files"
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS "public"."alumni_files" (
    "File_ID" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Alumni_ID" integer NOT NULL,
    "File_Type" alumni_file_type NOT NULL,
    "Original_Name" varchar(255),
    "Stored_Name" varchar(255) NOT NULL,
    "File_Path" varchar(500) NOT NULL,
    "Mime_Type" varchar(100),
    "File_Size" integer,
    "Uploaded_At" timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY ("File_ID")
);
ALTER TABLE "public"."alumni_files" ENABLE ROW LEVEL SECURITY;

