-- ----------------------------------------------------------------------------
-- Table: "public"."payments"
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS "public"."payments" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "transaction_ref" varchar(64) NOT NULL,
    "alumni_id" integer,
    "student_number" varchar(50),
    "payer_name" varchar(255) NOT NULL,
    "payer_email" varchar(255),
    "payer_contact" varchar(50),
    "campus_id" integer,
    "college_id" integer,
    "payment_type" payment_type DEFAULT 'alumni_id'::payment_type NOT NULL,
    "payment_purpose_id" integer NOT NULL,
    "description" varchar(255),
    "amount" numeric(10, 2) DEFAULT 0.00 NOT NULL,
    "payment_method" payment_method DEFAULT 'cash'::payment_method NOT NULL,
    "channel_reference" varchar(100),
    "status" payment_status DEFAULT 'pending'::payment_status NOT NULL,
    "proof_file" varchar(255),
    "submitted_by_role" varchar(50) DEFAULT 'alumni'::character varying,
    "coordinator_id" integer,
    "notes" text,
    "verified_by" integer,
    "verified_at" timestamp,
    "created_at" timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" timestamp DEFAULT CURRENT_TIMESTAMP NOT NULL,
    PRIMARY KEY ("id")
);
ALTER TABLE "public"."payments" ENABLE ROW LEVEL SECURITY;

